import { test, expect } from '@playwright/test';

test.describe('Browser Back Button Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should navigate back to previous page without losing app state', async ({ page }) => {
    // Navigate to a page with complex state
    await page.goto('/settings');
    const settingsTitle = page.getByRole('heading', { name: /settings/i });
    await expect(settingsTitle).toBeVisible();

    // Verify initial state
    const profileName = page.getByLabel(/profile name/i);
    await expect(profileName).toHaveValue('John Doe');

    // Navigate to another page
    await page.goto('/profile');
    const profileTitle = page.getByRole('heading', { name: /profile/i });
    await expect(profileTitle).toBeVisible();

    // Verify state is preserved
    await expect(profileName).toHaveValue('John Doe');

    // Navigate back using browser back button
    await page.goBack();

    // Verify we are back on settings page
    await expect(settingsTitle).toBeVisible();

    // Verify state is preserved after going back
    await expect(profileName).toHaveValue('John Doe');

    // Verify settings form is still visible
    const settingsForm = page.getByRole('form');
    await expect(settingsForm).toBeVisible();
  });

  test('should handle multiple back navigations and maintain correct state', async ({ page }) => {
    // Navigate to page 1
    await page.goto('/dashboard');
    const dashboardTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardTitle).toBeVisible();

    // Navigate to page 2
    await page.goto('/settings');
    const settingsTitle = page.getByRole('heading', { name: /settings/i });
    await expect(settingsTitle).toBeVisible();

    // Navigate to page 3
    await page.goto('/profile');
    const profileTitle = page.getByRole('heading', { name: /profile/i });
    await expect(profileTitle).toBeVisible();

    // Verify state on page 3
    const profileName = page.getByLabel(/profile name/i);
    await expect(profileName).toHaveValue('Jane Smith');

    // Navigate back to page 2
    await page.goBack();
    await expect(settingsTitle).toBeVisible();
    await expect(profileName).toHaveValue('Jane Smith');

    // Navigate back to page 1
    await page.goBack();
    await expect(dashboardTitle).toBeVisible();
    await expect(profileName).toHaveValue('Jane Smith');

    // Navigate back to page 2 again
    await page.goBack();
    await expect(settingsTitle).toBeVisible();
    await expect(profileName).toHaveValue('Jane Smith');

    // Navigate back to page 3 again
    await page.goBack();
    await expect(profileTitle).toBeVisible();
    await expect(profileName).toHaveValue('Jane Smith');
  });
});
